WITH flattened_attrs AS (SELECT id, effective_from, tier_limits, discounts, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers WHERE effective_from <= '2025-08-01') SELECT id, effective_from, avg_tier_price, SUM(entry_price) OVER (ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_entry_price, LEAD(avg_tier_price, 1) OVER (ORDER BY effective_from, id) AS next_avg_tier_price, AVG(avg_tier_price) OVER (ORDER BY entry_price, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS avg_tier_price_avg_2_prior, FIRST_VALUE(avg_tier_price) IGNORE NULLS OVER (ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_avg_tier_price FROM flattened_attrs WHERE effective_from BETWEEN '2024-11-01' AND '2024-11-14';
